cat > counter.go <<'EOF'
package main

// Core line counting state machine.

const (
	sBlank             = 1
	sCode              = 2
	sComment           = 3
	sCommentCode       = 4
	sMulticomment      = 5
	sMulticommentCode  = 6
	sMulticommentBlank = 7
	sString            = 8
	sDocString         = 9
)

const (
	tString     = 1
	tSlcomment  = 2
	tMlcomment  = 3
	tComplexity = 4
)

type trieNode struct {
	table [256]*trieNode
	typ   int
	close []byte
}

func (n *trieNode) insert(typ int, tok []byte, close []byte) {
	node := n
	for _, c := range tok {
		if node.table[c] == nil {
			node.table[c] = &trieNode{}
		}
		node = node.table[c]
	}
	node.typ = typ
	node.close = close
}

// match walks the trie as deep as possible and returns the type of the
// node where the walk stopped.
func (n *trieNode) match(content []byte, i int) (int, int, []byte) {
	node := n
	l := len(content)
	if i >= l {
		return 0, 0, nil
	}
	for d := i; d < l; d++ {
		nx := node.table[content[d]]
		if nx == nil {
			return node.typ, d - i, node.close
		}
		node = nx
	}
	return node.typ, l - 1 - i, node.close
}

type quoteDef struct {
	start        []byte
	end          []byte
	ignoreEscape bool
	docString    bool
}

type langFeatures struct {
	tokens   *trieNode
	mlTrie   *trieNode
	nested   bool
	quotes   []quoteDef
	hasLC    bool
	hasML    bool
	hasCX    bool
	hasQuote bool
}

func buildFeatures(l *Language, complexity bool) *langFeatures {
	lf := &langFeatures{tokens: &trieNode{}, mlTrie: &trieNode{}, nested: l.Nested}
	for _, p := range l.Paths {
		lf.tokens.insert(0, []byte(p), nil)
	}
	if complexity {
		for _, c := range l.ComplexityChecks {
			lf.tokens.insert(tComplexity, []byte(c), nil)
			lf.hasCX = true
		}
	}
	for _, c := range l.LineComment {
		lf.tokens.insert(tSlcomment, []byte(c), nil)
		lf.hasLC = true
	}
	for _, m := range l.MultiLine {
		lf.tokens.insert(tMlcomment, []byte(m[0]), []byte(m[1]))
		lf.mlTrie.insert(tMlcomment, []byte(m[0]), []byte(m[1]))
		lf.hasML = true
	}
	for _, q := range l.Quotes {
		qd := quoteDef{start: []byte(q.Start), end: []byte(q.End), ignoreEscape: q.IgnoreEscape, docString: q.DocString}
		lf.quotes = append(lf.quotes, qd)
		lf.tokens.insert(tString, qd.start, qd.end)
		lf.hasQuote = true
	}
	return lf
}

func (lf *langFeatures) match(content []byte, i int) (int, int, []byte) {
	typ, off, close := lf.tokens.match(content, i)
	if typ != 0 {
		return typ, off, close
	}
	var best *quoteDef
	for k := range lf.quotes {
		q := &lf.quotes[k]
		if hasPrefixAt(content, i, q.start) && (best == nil || len(q.start) > len(best.start)) {
