func (lf *langFeatures) commentState(content []byte, index, endPoint, state int, endComments [][]byte) (int, int, [][]byte) {
	for i := index; i < endPoint; i++ {
		b := content[i]
		index = i
		if b == '\n' {
			return state, i, endComments
		}
		if checkForMatchSingle(b, index, endPoint, endComments[len(endComments)-1], content) {
			off := len(endComments[len(endComments)-1])
			endComments = endComments[:len(endComments)-1]
			if len(endComments) == 0 {
				if state == sMulticommentCode {
