package main

import (
	"bytes"
	"encoding/csv"
	"fmt"
	"strconv"
	"strings"
)

type flagKind int

const (
	kBool flagKind = iota
	kString
	kInt
	kFloat
	kStringSlice
	kStringArray
)

type flagDef struct {
	name      string
	short     string
	kind      flagKind
	changed   bool
	boolPtr   *bool
	strPtr    *string
	intPtr    *int64
	floatPtr  *float64
	slicePtr  *[]string
	typeName  string
}

type flagSet struct {
	defs  []*flagDef
	long  map[string]*flagDef
	short map[string]*flagDef
	args  []string
}

func newFlagSet() *flagSet {
	return &flagSet{long: map[string]*flagDef{}, short: map[string]*flagDef{}}
}

func (fs *flagSet) add(d *flagDef) {
	fs.defs = append(fs.defs, d)
	fs.long[d.name] = d
	if d.short != "" {
		fs.short[d.short] = d
	}
}

func (fs *flagSet) Bool(p *bool, name, short string, def bool) {
	*p = def
	fs.add(&flagDef{name: name, short: short, kind: kBool, boolPtr: p, typeName: "bool"})
}
func (fs *flagSet) String(p *string, name, short string, def string) {
	*p = def
	fs.add(&flagDef{name: name, short: short, kind: kString, strPtr: p, typeName: "string"})
}
func (fs *flagSet) Int(p *int64, name, short string, def int64) {
	*p = def
	fs.add(&flagDef{name: name, short: short, kind: kInt, intPtr: p, typeName: "int"})
}
func (fs *flagSet) Float(p *float64, name, short string, def float64) {
	*p = def
	fs.add(&flagDef{name: name, short: short, kind: kFloat, floatPtr: p, typeName: "float64"})
}
func (fs *flagSet) StringSlice(p *[]string, name, short string, def []string) {
	*p = def
	fs.add(&flagDef{name: name, short: short, kind: kStringSlice, slicePtr: p, typeName: "stringSlice"})
}
func (fs *flagSet) StringArray(p *[]string, name, short string, def []string) {
	*p = def
	fs.add(&flagDef{name: name, short: short, kind: kStringArray, slicePtr: p, typeName: "stringArray"})
}

func readAsCSV(val string) ([]string, error) {
	if val == "" {
		return []string{}, nil
	}
	stringReader := strings.NewReader(val)
	csvReader := csv.NewReader(stringReader)
	return csvReader.Read()
}

func (d *flagDef) displayName() string {
	if d.short != "" {
		return "-" + d.short + ", --" + d.name
	}
	return "--" + d.name
}

func (d *flagDef) set(val string) error {
	switch d.kind {
	case kBool:
		b, err := strconv.ParseBool(val)
		if err != nil {
			return err
		}
		*d.boolPtr = b
	case kString:
		*d.strPtr = val
	case kInt:
		v, err := strconv.ParseInt(val, 0, 64)
		if err != nil {
			return err
		}
		*d.intPtr = v
	case kFloat:
		v, err := strconv.ParseFloat(val, 64)
		if err != nil {
			return err
		}
		*d.floatPtr = v
	case kStringSlice:
		v, err := readAsCSV(val)
		if err != nil {
			return err
		}
		if !d.changed {
			*d.slicePtr = v
		} else {
			*d.slicePtr = append(*d.slicePtr, v...)
		}
	case kStringArray:
		if !d.changed {
			*d.slicePtr = []string{val}
		} else {
			*d.slicePtr = append(*d.slicePtr, val)
		}
	}
	d.changed = true
	return nil
}

func (fs *flagSet) setFlag(d *flagDef, val string) error {
	if err := d.set(val); err != nil {
		return fmt.Errorf("invalid argument %q for %q flag: %v", val, d.displayName(), err)
	}
	return nil
}

func (fs *flagSet) parse(arguments []string) error {
	args := arguments
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			fs.args = append(fs.args, s)
			continue
		}
		if s[1] == '-' {
			if len(s) == 2 {
				fs.args = append(fs.args, args...)
				break
			}
			name := s[2:]
			if len(name) == 0 || name[0] == '-' || name[0] == '=' {
				return fmt.Errorf("bad flag syntax: %s", s)
			}
			split := strings.SplitN(name, "=", 2)
			name = split[0]
			d, ok := fs.long[name]
			if !ok {
				if name == "help" {
					return errHelp
				}
				return fmt.Errorf("unknown flag: --%s", name)
			}
			var value string
			if len(split) == 2 {
				value = split[1]
			} else if d.kind == kBool {
				value = "true"
			} else if len(args) > 0 {
				value = args[0]
				args = args[1:]
			} else {
				return fmt.Errorf("flag needs an argument: %s", s)
			}
			if err := fs.setFlag(d, value); err != nil {
				return err
			}
			if d.name == "help" && *d.boolPtr {
				return errHelp
			}
		} else {
			shorthands := s[1:]
			for len(shorthands) > 0 {
				c := shorthands[:1]
				d, ok := fs.short[c]
				if !ok {
					if c == "h" {
						return errHelp
					}
					return fmt.Errorf("unknown shorthand flag: %q in -%s", c[0], shorthands)
				}
				var value string
				rest := shorthands[1:]
				if len(shorthands) > 2 && shorthands[1] == '=' {
					value = shorthands[2:]
					shorthands = ""
				} else if d.kind == kBool {
					value = "true"
					shorthands = rest
				} else if len(rest) > 0 {
					value = rest
					shorthands = ""
				} else if len(args) > 0 {
					value = args[0]
					args = args[1:]
					shorthands = ""
				} else {
					return fmt.Errorf("flag needs an argument: %q in -%s", c[0], shorthands)
				}
				if err := fs.setFlag(d, value); err != nil {
					return err
				}
				if d.name == "help" && *d.boolPtr {
					return errHelp
				}
			}
		}
	}
	return nil
}

type helpError struct{}

func (helpError) Error() string { return "help requested" }

var errHelp = helpError{}

var _ = bytes.NewBuffer
EOF
