package main

import (
	"path/filepath"
	"sort"
	"strings"
)

// getExtension2 mimics two-level extension extraction.
func getExtension2(name string) string {
	ext := filepath.Ext(name)
	if ext == "" || strings.LastIndex(name, ".") == 0 {
		return name
	}
	ext2 := filepath.Ext(strings.TrimSuffix(name, ext))
	return strings.TrimPrefix(ext2+ext, ".")
}

// detectLanguage returns possible languages and the extension for a file name.
// content is used for shebang detection when needed (may be nil -> loaded lazily via loader)
func detectLanguage(name string, loader func() []byte) ([]string, string) {
	lname := strings.ToLower(name)
	dots := strings.Count(name, ".")
	if dots == 0 || (name[0] == '.' && dots == 1) {
		if lang, ok := filenameToLanguage[lname]; ok {
			return []string{lang}, name
		}
		if loader != nil {
			content := loader()
			if lang := detectShebang(content); lang != "" {
				return []string{lang}, name
			}
		}
		return nil, name
	}
