var startTime = time.Now()

func printWarn(msg string) {
	fmt.Printf("WARN %s: %s\n", time.Now().UTC().Format(time.RFC3339), msg)
}
func printDebug(msg string) {
	if Debug {
		fmt.Printf("DEBUG %s: %s\n", time.Now().UTC().Format(time.RFC3339), msg)
	}
}
func printTrace(msg string) {
	if Trace {
		fmt.Printf("TRACE %s: %s\n", time.Now().UTC().Format(time.RFC3339), msg)
	}
}

type remapRule struct {
	match string
	lang  string
}

func parseRemap(s string) []remapRule {
	var out []remapRule
	if s == "" {
		return out
	}
	for _, part := range strings.Split(s, ",") {
		idx := strings.LastIndex(part, ":")
		if idx == -1 {
			continue
		}
		out = append(out, remapRule{match: part[:idx], lang: part[idx+1:]})
	}
	return out
}

var (
	remapAllRules     []remapRule
	remapUnknownRules []remapRule
	excludeRegexes    []*regexp.Regexp
)

func setupCountAs() {
	if CountAs == "" {
		return
	}
	for _, part := range strings.Split(CountAs, ",") {
		idx := strings.Index(part, ":")
		if idx == -1 {
			continue
		}
		ext := strings.ToLower(part[:idx])
		target := part[idx+1:]
		if l, ok := languageByLowerName[strings.ToLower(target)]; ok {
			extensionToLanguage[ext] = l.Name
			delete(db.Ambiguous, ext)
			continue
		}
		if lang, ok := extensionToLanguage[strings.ToLower(target)]; ok {
			extensionToLanguage[ext] = lang
			delete(db.Ambiguous, ext)
		}
	}
}

func process(paths []string) int {
	// option implications
	if IgnoreMinified {
		Minified = true
	}
	if IgnoreGenerated {
		Generated = true
	}
	if IgnoreMinifiedGenerated {
		MinifiedGenerated = true
	}
	if MinifiedGenerated {
		Minified = true
		Generated = true
	}
	if Dryness {
		UlocMode = true
	}
	setupCountAs()
	remapAllRules = parseRemap(RemapAll)
	remapUnknownRules = parseRemap(RemapUnknown)
	for _, e := range Exclude {
		re, err := regexp.Compile(e)
		if err != nil {
			fmt.Println(err.Error())
			return 1
		}
		excludeRegexes = append(excludeRegexes, re)
	}

	for _, p := range paths {
		if _, err := os.Stat(p); err != nil {
			fmt.Printf("file or directory could not be read: %s\n", p)
			return 1
		}
	}

	printDebugConfig()

	files := walkPaths(paths)
	jobs := processFiles(files)
	return output(jobs)
