	printDebug(fmt.Sprintf("White List: %v", AllowListExtensions))
	printDebug(fmt.Sprintf("Files Output: %v", Files))
	printDebug(fmt.Sprintf("Verbose: %v", Verbose))
	printDebug(fmt.Sprintf("Duplicates Detection: %v", Duplicates))
	printDebug(fmt.Sprintf("Complexity Calculation: %v", Complexity))
	printDebug(fmt.Sprintf("Wide: %v", More))
	printDebug(fmt.Sprintf("Average Wage: %d", AverageWage))
	printDebug(fmt.Sprintf("Cocomo: %v", !NoCocomo))
	printDebug(fmt.Sprintf("Locomo: %v", Locomo))
