func parseRemap(s string) []remapRule {
	var out []remapRule
	if s == "" {
		return out
	}
	for _, part := range strings.Split(s, ",") {
		idx := strings.LastIndex(part, ":")
		if idx == -1 {
			continue
		}
		out = append(out, remapRule{match: part[:idx], lang: part[idx+1:]})
	}
	return out
}

var (
	remapAllRules     []remapRule
	remapUnknownRules []remapRule
	excludeRegexes    []*regexp.Regexp
)

func setupCountAs() {
	if CountAs == "" {
		return
	}
	for _, part := range strings.Split(CountAs, ",") {
		idx := strings.Index(part, ":")
		if idx == -1 {
			continue
		}
		ext := strings.ToLower(part[:idx])
		target := part[idx+1:]
		if l, ok := languageByLowerName[strings.ToLower(target)]; ok {
			extensionToLanguage[ext] = l.Name
			delete(db.Ambiguous, ext)
			continue
		}
		if lang, ok := extensionToLanguage[strings.ToLower(target)]; ok {
			extensionToLanguage[ext] = lang
			delete(db.Ambiguous, ext)
		}
	}
}

func process(paths []string) int {
	// option implications
	if IgnoreMinified {
		Minified = true
	}
	if IgnoreGenerated {
		Generated = true
	}
	if IgnoreMinifiedGenerated {
		MinifiedGenerated = true
	}
	if MinifiedGenerated {
		Minified = true
		Generated = true
	}
	if Dryness {
		UlocMode = true
	}
	setupCountAs()
	remapAllRules = parseRemap(RemapAll)
	remapUnknownRules = parseRemap(RemapUnknown)
	for _, e := range Exclude {
		re, err := regexp.Compile(e)
		if err != nil {
			fmt.Println(err.Error())
			return 1
		}
		excludeRegexes = append(excludeRegexes, re)
	}

	for _, p := range paths {
		if _, err := os.Stat(p); err != nil {
			fmt.Printf("file or directory could not be read: %s\n", p)
			return 1
		}
	}

	printDebugConfig()

	files := walkPaths(paths)
	jobs := processFiles(files)
	return output(jobs)
}

func printDebugConfig() {
	if !Debug {
		return
	}
	printDebug(fmt.Sprintf("Path Deny List: %v", PathDenyList))
	printDebug(fmt.Sprintf("Sort By: %s", SortBy))
	printDebug(fmt.Sprintf("White List: %v", AllowListExtensions))
	printDebug(fmt.Sprintf("Files Output: %v", Files))
	printDebug(fmt.Sprintf("Verbose: %v", Verbose))
	printDebug(fmt.Sprintf("Duplicates Detection: %v", Duplicates))
	printDebug(fmt.Sprintf("Complexity Calculation: %v", Complexity))
	printDebug(fmt.Sprintf("Wide: %v", More))
	printDebug(fmt.Sprintf("Average Wage: %d", AverageWage))
	printDebug(fmt.Sprintf("Cocomo: %v", !NoCocomo))
	printDebug(fmt.Sprintf("Locomo: %v", Locomo))
	printDebug(fmt.Sprintf("Minified/Generated Detection: %v/%v", Minified, Generated))
	printDebug(fmt.Sprintf("Ignore Minified/Generated: %v/%v", IgnoreMinified, IgnoreGenerated))
	printDebug(fmt.Sprintf("IncludeSymLinks: %v", IncludeSymLinks))
	printDebug(fmt.Sprintf("Uloc: %v", UlocMode))
	printDebug(fmt.Sprintf("Dryness: %v", Dryness))
	printDebug(fmt.Sprintf("NumCPU: %d", 64))
	printDebug(fmt.Sprintf("SortBy: %s", SortBy))
	printDebug(fmt.Sprintf("PathDenyList: %v", PathDenyList))
}

type foundFile struct {
	location    string
	filename    string
	symlocation string
}

func processFiles(files []foundFile) []*FileJob {
	var jobs []*FileJob
	seenHash := map[[16]byte]bool{}
	for _, f := range files {
		job := processFile(f)
		if job == nil {
			continue
		}
		if Duplicates {
			h := md5.Sum(job.Content)
			if seenHash[h] {
				if Verbose {
					printWarn(fmt.Sprintf("skipping duplicate file: %s", job.Location))
				}
				continue
			}
			seenHash[h] = true
			job.Hash = h[:]
		}
		job.Content = nil
		jobs = append(jobs, job)
	}
	return jobs
}

func isIgnoreFileName(name string) bool {
	return name == ".gitignore" || name == ".ignore"
}

func processFile(f foundFile) *FileJob {
	name := filepath.Base(f.filename)
	if strings.Contains(f.filename, "/") {
		name = filepath.Base(f.filename)
	}
	var content []byte
	loaded := false
	loader := func() []byte {
		if !loaded {
			content, _ = os.ReadFile(f.location)
			loaded = true
		}
		return content
	}
	possible, ext := detectLanguage(name, loader)
	language := ""
	if len(possible) > 0 {
		language = possible[0]
	}
	if !CountIgnore && isIgnoreFileName(name) && (language == "gitignore" || language == "ignore") {
		return nil
	}
	// filters
	for _, x := range ExcludeFilename {
		if strings.Contains(name, x) {
			return nil
		}
	}
	if len(AllowListExtensions) > 0 {
		ok := false
		for _, a := range AllowListExtensions {
			if ext == a && language != "" {
				ok = true
			}
		}
		if !ok {
			return nil
		}
	}
	for _, x := range ExcludeExt {
		if ext == x {
			return nil
		}
	}
	if language == "" && len(remapUnknownRules) == 0 && len(remapAllRules) == 0 {
		return nil
	}
	content = loader()
	if content == nil {
		content = []byte{}
	}
	remapped := false
	if language == "" {
		for _, r := range remapUnknownRules {
			if strings.Contains(string(content), r.match) {
				language = r.lang
				possible = []string{r.lang}
				remapped = true
				break
			}
		}
	}
	for _, r := range remapAllRules {
		if strings.Contains(string(content), r.match) {
			language = r.lang
			possible = []string{r.lang}
			remapped = true
			break
		}
	}
	if language == "" {
		return nil
	}
	job := &FileJob{
		Language:          language,
		PossibleLanguages: possible,
		Filename:          f.filename,
		Extension:         ext,
		Location:          f.location,
		Symlocation:       f.symlocation,
		Content:           content,
		Bytes:             int64(len(content)),
		remapped:          remapped,
	}
	if !remapped {
		if len(possible) > 1 {
			lang, guessed := determineLanguage(name, language, possible, content)
			job.Language = lang
			if guessed && Verbose {
				printWarn(fmt.Sprintf("guessing language %s for file %s", lang, job.Location))
			}
		} else if cf := cloudFormationCheck(ext, content); cf != "" && (language == "YAML" || language == "JSON") {
			job.Language = cf
			if Verbose {
				printWarn(fmt.Sprintf("guessing language %s for file %s", cf, job.Location))
			}
		}
	}
	if !countJob(job) {
		return nil
	}
	if NoLarge {
		if job.Lines >= LargeLineCount {
			if Verbose {
				printWarn(fmt.Sprintf("skipping large file due to line length: %s", job.Location))
			}
			return nil
		}
		if job.Bytes >= LargeByteCount {
			if Verbose {
				printWarn(fmt.Sprintf("skipping large file due to byte size: %s", job.Location))
			}
			return nil
		}
	}
	// minified / generated
	if Generated {
		head := job.Content
		if len(head) > 1000 {
			head = head[:1000]
		}
		lower := strings.ToLower(string(head))
		for _, m := range GeneratedMarkers {
			if strings.Contains(lower, strings.ToLower(m)) {
				job.Generated = true
				break
			}
		}
	}
	if Minified && !job.Generated && job.Lines > 0 {
		if job.Bytes/job.Lines >= MinifiedGeneratedLineByteLength {
			job.Minified = true
		}
	}
	if job.Generated {
		if IgnoreGenerated || IgnoreMinifiedGenerated {
			if Verbose {
				printWarn(fmt.Sprintf("skipping generated file: %s", job.Location))
			}
			return nil
		}
		job.Language = job.Language + " (gen)"
	} else if job.Minified {
		if IgnoreMinified || IgnoreMinifiedGenerated {
			if Verbose {
				printWarn(fmt.Sprintf("skipping minified file: %s", job.Location))
			}
			return nil
		}
		job.Language = job.Language + " (min)"
	}
	return job
}

func countJob(job *FileJob) bool {
	var lf *langFeatures
	if job.remapped {
		lf = buildFeatures(&Language{Name: job.Language}, Complexity)
	} else {
		lf = getFeatures(job.Language)
	}
	track := UlocMode || MaxMean || Trace
	res := countStats(job.Content, lf, track)
	if res.binary {
		if Verbose {
			printWarn(fmt.Sprintf("skipping file identified as binary: %s", job.Location))
		}
		return false
	}
	job.Lines = res.Lines
	job.Code = res.Code
	job.Comment = res.Comment
	job.Blank = res.Blank
	job.Complexity = res.Complexity
	job.lineTypes = res.lineTypes
	if Trace {
		for i, lt := range res.lineTypes {
			name := "blank"
			switch lt {
			case lineCode:
				name = "code"
			case lineComment:
				name = "comment"
			}
			printTrace(fmt.Sprintf("%s line %d ended with state: %d: counted as %s", job.Location, i+1, res.lineStates[i], name))
		}
	}
	if MaxMean || UlocMode {
		job.LineLength = lineLengths(job.Content)
	}
	if More && job.Code > 0 {
		job.WeightedComplexity = float64(job.Complexity) / float64(job.Code) * 100
	}
	return true
}

func lineLengths(content []byte) []int {
	var out []int
	start := 0
	for i, b := range content {
		if b == '\n' {
			out = append(out, i-start)
			start = i + 1
		}
	}
	if start < len(content) {
		out = append(out, len(content)-start)
	}
	return out
}

var _ = sort.Strings
