package main

import (
	"bufio"
	"bytes"
	"os"
	"regexp"
	"strings"
)

type ignorePattern struct {
	re       *regexp.Regexp
	negate   bool
	dirOnly  bool
	anchored bool
}

type ignoreFile struct {
	base     string // relative dir (from walk root) of the ignore file, "" for root
	patterns []ignorePattern
}

func globToRegex(p string) string {
	var sb strings.Builder
	i := 0
	for i < len(p) {
		c := p[i]
		switch c {
		case '*':
			if i+1 < len(p) && p[i+1] == '*' {
				// double star
				if i+2 < len(p) && p[i+2] == '/' {
					sb.WriteString("(?:.*/)?")
					i += 3
					continue
				}
				sb.WriteString(".*")
				i += 2
				continue
			}
			sb.WriteString("[^/]*")
		case '?':
			sb.WriteString("[^/]")
		case '[':
			j := i + 1
			if j < len(p) && (p[j] == '!' || p[j] == '^') {
				j++
			}
			if j < len(p) && p[j] == ']' {
				j++
			}
			for j < len(p) && p[j] != ']' {
				j++
			}
			if j >= len(p) {
				sb.WriteString("\\[")
			} else {
				cls := p[i+1 : j]
				if len(cls) > 0 && cls[0] == '!' {
					cls = "^" + cls[1:]
				}
				cls = strings.ReplaceAll(cls, "\\", "\\\\")
				sb.WriteString("[" + cls + "]")
				i = j
			}
		case '\\':
			if i+1 < len(p) {
				sb.WriteString(regexp.QuoteMeta(string(p[i+1])))
				i++
			} else {
				sb.WriteString("\\\\")
			}
		default:
			sb.WriteString(regexp.QuoteMeta(string(c)))
		}
		i++
	}
	return sb.String()
}

func parseIgnoreFile(path string, base string) *ignoreFile {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	f := &ignoreFile{base: base}
	sc := bufio.NewScanner(bytes.NewReader(data))
	sc.Buffer(make([]byte, 1024*1024), 1024*1024*16)
	for sc.Scan() {
		line := strings.TrimRight(sc.Text(), "\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		// trim trailing unescaped spaces
		for strings.HasSuffix(line, " ") && !strings.HasSuffix(line, "\\ ") {
			line = line[:len(line)-1]
		}
		if line == "" {
			continue
		}
		pat := ignorePattern{}
		if strings.HasPrefix(line, "!") {
			pat.negate = true
			line = line[1:]
		} else if strings.HasPrefix(line, "\\!") || strings.HasPrefix(line, "\\#") {
			line = line[1:]
		}
		if strings.HasSuffix(line, "/") {
			pat.dirOnly = true
			line = strings.TrimRight(line, "/")
		}
		if line == "" {
			continue
		}
		if strings.Contains(line, "/") {
			pat.anchored = true
			line = strings.TrimPrefix(line, "/")
		}
		expr := globToRegex(line)
		if pat.anchored {
			expr = "^" + expr + "(?:/.*)?$"
		} else {
			expr = "^" + expr + "$"
		}
		re, err := regexp.Compile(expr)
		if err != nil {
			continue
		}
		pat.re = re
		f.patterns = append(f.patterns, pat)
	}
	return f
}

// match returns (matched, ignored)
func (f *ignoreFile) match(rel string, name string, isDir bool) (bool, bool) {
	// rel is relative to walk root using "/" separators
	r := rel
	if f.base != "" {
		if !strings.HasPrefix(rel, f.base+"/") {
			return false, false
		}
		r = rel[len(f.base)+1:]
	}
	matched := false
	ignored := false
	for _, p := range f.patterns {
		if p.dirOnly && !isDir {
			continue
		}
		var ok bool
		if p.anchored {
			ok = p.re.MatchString(r)
		} else {
			ok = p.re.MatchString(name)
		}
		if ok {
			matched = true
			ignored = !p.negate
		}
	}
	return matched, ignored
}

func parseGitModules(path string) []string {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var out []string
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "path") {
			parts := strings.SplitN(line, "=", 2)
			if len(parts) == 2 && strings.TrimSpace(parts[0]) == "path" {
				out = append(out, strings.TrimSpace(parts[1]))
			}
		}
	}
	return out
}
