package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type walkState struct {
	seen  map[string]bool
	files []foundFile
}

func walkPaths(paths []string) []foundFile {
	ws := &walkState{seen: map[string]bool{}}
	for _, p := range paths {
		info, err := os.Lstat(p)
		if err != nil {
			continue
		}
		if info.Mode()&os.ModeSymlink != 0 {
			st, err := os.Stat(p)
			if err != nil {
				continue
			}
			if st.IsDir() {
				ws.walkDir(p, "", nil, nil)
				continue
			}
			if !IncludeSymLinks {
				continue
			}
			target, _ := os.Readlink(p)
			loc := filepath.Clean(p)
			if !ws.seen[loc] {
				ws.seen[loc] = true
				ws.files = append(ws.files, foundFile{location: loc, filename: loc, symlocation: target})
			}
			continue
		}
		if info.IsDir() {
			ws.walkDir(p, "", nil, nil)
		} else {
			loc := filepath.Clean(p)
			if !ws.seen[loc] {
				ws.seen[loc] = true
				ws.files = append(ws.files, foundFile{location: loc, filename: loc})
			}
		}
	}
	return ws.files
}

func (ws *walkState) walkDir(root string, rel string, ignores []*ignoreFile, modules []string) {
	dir := root
	if rel != "" {
		dir = filepath.Join(root, rel)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	// load ignore files of this directory
	newIgnores := ignores
	add := func(name string) {
		if f := parseIgnoreFile(filepath.Join(dir, name), rel); f != nil {
			newIgnores = append(append([]*ignoreFile{}, newIgnores...), f)
		}
	}
	if GitIgnore {
		add(".gitignore")
	}
	if Ignore {
		add(".ignore")
	}
	if SccIgnore {
		add(".sccignore")
	}
	newModules := modules
	if GitModuleIgnore {
		for _, m := range parseGitModules(filepath.Join(dir, ".gitmodules")) {
			p := m
			if rel != "" {
				p = rel + "/" + m
			}
			newModules = append(append([]string{}, newModules...), filepath.Clean(p))
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
	var dirs []string
	for _, e := range entries {
		name := e.Name()
		childRel := name
		if rel != "" {
			childRel = rel + "/" + name
		}
		if e.Type()&os.ModeSymlink != 0 {
			continue
		}
		isDir := e.IsDir()
		if isIgnored(newIgnores, childRel, name, isDir) {
			continue
		}
		loc := filepath.Join(root, childRel)
		if isDir {
			if denyDir(name, loc, childRel) {
				continue
			}
			skip := false
			for _, m := range newModules {
				if m == childRel {
					skip = true
				}
			}
			if skip {
				continue
			}
			excluded := false
			for _, re := range excludeRegexes {
				if re.MatchString(name) {
					excluded = true
					break
				}
			}
			if excluded {
				continue
			}
			dirs = append(dirs, childRel)
			continue
		}
		if !e.Type().IsRegular() {
			continue
		}
		excluded := false
		for _, re := range excludeRegexes {
			if re.MatchString(name) || re.MatchString(loc) {
				excluded = true
				break
			}
		}
		if excluded {
			continue
		}
		if ws.seen[loc] {
			continue
		}
		ws.seen[loc] = true
		ws.files = append(ws.files, foundFile{location: loc, filename: name})
	}
	for _, d := range dirs {
		ws.walkDir(root, d, newIgnores, newModules)
	}
}

func denyDir(name, loc, rel string) bool {
	for _, d := range PathDenyList {
		d2 := strings.TrimRight(d, "/")
		if d2 == "" {
			continue
		}
		if name == d2 || loc == d2 || rel == d2 || filepath.Clean(loc) == filepath.Clean(d2) {
			return true
		}
	}
	return false
}

func isIgnored(ignores []*ignoreFile, rel, name string, isDir bool) bool {
	ignored := false
	for _, f := range ignores {
		if m, ig := f.match(rel, name, isDir); m {
			ignored = ig
		}
	}
	return ignored
}
