	}
	if LocomoOutputPrice > 0 {
		outPrice = LocomoOutputPrice
	}
	if LocomoTPS > 0 {
		tps = LocomoTPS
	}
	density := 0.0
	if code > 0 {
		density = float64(complexity) / float64(code)
	}
	if density > 1 {
		density = 1
	}
	sq := math.Sqrt(density)
	cycles := iterations + iterationWeight*sq
	if LocomoCycles > 0 {
		cycles = LocomoCycles
	}
	mult := cycles * (1 + complexityWeight*sq)
	out := float64(code) * tokensPerLine * cycles
	in := float64(code) * inputPerLine * mult
	r := locomoResult{
