func commaInt(v int64) string {
	sign := ""
	if v < 0 {
		sign = "-"
		v = -v
	}
	s := fmt.Sprintf("%d", v)
	n := len(s)
	if n <= 3 {
		return sign + s
	}
	var sb strings.Builder
	pre := n % 3
	if pre > 0 {
		sb.WriteString(s[:pre])
	}
	for i := pre; i < n; i += 3 {
		if sb.Len() > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(s[i : i+3])
	}
	return sign + sb.String()
}

// commaFloat formats with the given precision and thousands separators
func commaFloat(v float64, prec int) string {
	s := fmt.Sprintf("%.*f", prec, v)
	neg := strings.HasPrefix(s, "-")
	if neg {
		s = s[1:]
	}
	intPart := s
	frac := ""
	if idx := strings.Index(s, "."); idx != -1 {
		intPart = s[:idx]
		frac = s[idx:]
	}
	var iv int64
	fmt.Sscanf(intPart, "%d", &iv)
	out := commaInt(iv) + frac
	if neg {
		out = "-" + out
	}
	return out
}

