func aggregate(jobs []*FileJob) []*LanguageSummary {
	m := map[string]*LanguageSummary{}
	var order []string
	for _, j := range jobs {
		ls, ok := m[j.Language]
		if !ok {
			ls = &LanguageSummary{Name: j.Language}
