			},
			pctRow: func(files, lines, blanks, comments, code, cx float64) string {
				return fmt.Sprintf("%-15s%10s%12s%10s%10s%11s%11s", "Percentage", pct(files), pct(lines), pct(blanks), pct(comments), pct(code), pct(cx))
			},
			fileRow: func(loc string, lines, blanks, comments, code, cx int64, wc float64) string {
