func fileSummarize(jobs []*FileJob) string {
	var sb bytes.Buffer
	wide := More
	var lay tabLayout
	if wide {
		lay = wideLayout()
	} else {
		lay = narrowLayout()
	}
	breakCh := "─"
	if Ci {
		breakCh = "-"
	}
	BREAK := strings.Repeat(breakCh, lay.width) + "\n"
	MINOR := strings.Repeat("-", lay.width) + "\n"
	if NoHBorder {
		BREAK = ""
		MINOR = ""
	}
	langs := aggregate(jobs)
	sortSummaries(langs)

	var tFiles, tLines, tBlank, tComment, tCode, tCx, tBytes int64
	var tWC float64
	for _, l := range langs {
		tFiles += l.Count
		tLines += l.Lines
		tBlank += l.Blank
		tComment += l.Comment
		tCode += l.Code
		tCx += l.Complexity
		tBytes += l.Bytes
		tWC += l.WeightedComplexity
	}
	p := func(a, b int64) float64 {
		if b == 0 {
			return 0
		}
		return float64(a) / float64(b) * 100
	}

	sb.WriteString(BREAK)
	sb.WriteString(lay.head + "\n")
	sb.WriteString(BREAK)
	for i, l := range langs {
		sb.WriteString(lay.langRow(l.Name, l.Count, l.Lines, l.Blank, l.Comment, l.Code, l.Complexity, l.WeightedComplexity) + "\n")
		if Percent {
			sb.WriteString(lay.pctRow(p(l.Count, tFiles), p(l.Lines, tLines), p(l.Blank, tBlank), p(l.Comment, tComment), p(l.Code, tCode), p(l.Complexity, tCx)) + "\n")
		}
		if MaxMean {
			mx, mean := maxMeanOf(l.Files)
			sb.WriteString(lay.maxMean(mx, mean) + "\n")
		}
		if UlocMode && (wide || !Files) {
			sb.WriteString(lay.ulocRow(langUloc(l)) + "\n")
		}
		if Files {
			sb.WriteString(BREAK)
			files := append([]*FileJob{}, l.Files...)
			sortFiles(files)
			for _, f := range files {
				sb.WriteString(lay.fileRow(f.Location, f.Lines, f.Blank, f.Comment, f.Code, f.Complexity, f.WeightedComplexity) + "\n")
			}
			if UlocMode && !wide {
				sb.WriteString(lay.ulocRow(langUloc(l)) + "\n")
			}
			sb.WriteString(BREAK)
		} else if (Percent || UlocMode || (MaxMean && !wide)) && i != len(langs)-1 {
			sb.WriteString(MINOR)
		}
	}
	if !Files || len(langs) == 0 {
		sb.WriteString(BREAK)
	}
	sb.WriteString(lay.langRow("Total", tFiles, tLines, tBlank, tComment, tCode, tCx, tWC) + "\n")
	sb.WriteString(BREAK)
	if UlocMode {
		u := totalUloc(jobs)
		sb.WriteString(lay.ulocTotal(u) + "\n")
		if Dryness {
			d := 0.0
			if tLines > 0 {
				d = float64(u) / float64(tLines)
			}
			sb.WriteString(lay.dryness(d) + "\n")
		}
		sb.WriteString(BREAK)
	}
	if !NoCocomo {
		writeCocomo(&sb, tCode)
		if !wide {
			sb.WriteString(BREAK)
		}
	}
	if Locomo || CostComparison {
		writeLocomo(&sb, tCode, tCx)
		if !wide {
			sb.WriteString(BREAK)
		}
	}
	if !NoSize {
		sb.WriteString(sizeLine(tBytes) + "\n")
		sb.WriteString(BREAK)
	}
	return sb.String()
}

func maxMeanOf(files []*FileJob) (int, int) {
	mx := 0
	total := 0
	count := 0
	for _, f := range files {
		for _, l := range f.LineLength {
			if l > mx {
				mx = l
			}
			total += l
			count++
		}
	}
	mean := 0
	if count > 0 {
		mean = total / count
	}
	return mx, mean
}

func writeCocomo(sb *bytes.Buffer, code int64) {
	_, label := cocomoParams()
	effort := estimateEffort(code, Eaf)
	cost := estimateCost(effort, AverageWage, Overhead)
	schedule := estimateSchedule(effort)
	people := 0.0
	if schedule != 0 {
		people = effort / schedule
	}
	if SLOCCountFormat {
		p, _ := cocomoParams()
		sb.WriteString(fmt.Sprintf("Total Physical Source Lines of Code (SLOC)                     = %s\n", commaInt(code)))
		sb.WriteString(fmt.Sprintf("Development Effort Estimate, Person-Years (Person-Months)      = %s (%s)\n", commaFloat(effort/12, 2), commaFloat(effort, 2)))
		sb.WriteString(fmt.Sprintf(" (Basic COCOMO model, Person-Months = %.2f*(KSLOC**%.2f)*%.2f)\n", p[0], p[1], Eaf))
		sb.WriteString(fmt.Sprintf("Schedule Estimate, Years (Months)                              = %s (%s)\n", commaFloat(schedule/12, 2), commaFloat(schedule, 2)))
		sb.WriteString(fmt.Sprintf(" (Basic COCOMO model, Months = %.2f*(person-months**%.2f))\n", p[2], p[3]))
		sb.WriteString(fmt.Sprintf("Estimated Average Number of Developers (Effort/Schedule)       = %s\n", commaFloat(people, 2)))
		sb.WriteString(fmt.Sprintf("Total Estimated Cost to Develop                                = %s%s\n", CurrencySymbol, commaInt(int64(cost))))
		sb.WriteString(fmt.Sprintf(" (average salary = %s%s/year, overhead = %.2f)\n", CurrencySymbol, commaInt(AverageWage), Overhead))
		return
	}
	sb.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s%s\n", label, CurrencySymbol, commaInt(int64(cost))))
	sb.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %s months\n", label, commaFloat(schedule, 2)))
	sb.WriteString(fmt.Sprintf("Estimated People Required (%s) %s\n", label, commaFloat(people, 2)))
}

func formatGenTime(s float64) string {
	if s <= 3600 {
		return fmt.Sprintf("%s minutes", commaFloat(s/60, 1))
	}
	if s <= 86400 {
		return fmt.Sprintf("%s hours", commaFloat(s/3600, 1))
	}
	return fmt.Sprintf("%s days", commaFloat(s/86400, 1))
}

func writeLocomo(sb *bytes.Buffer, code, cx int64) {
	r := computeLocomo(code, cx)
	sb.WriteString(fmt.Sprintf("LOCOMO LLM Cost Estimate (%s)\n", r.Preset))
	sb.WriteString(fmt.Sprintf("  Tokens Required (in/out) %sM / %sM\n", commaFloat(r.InputTokens/1000000, 1), commaFloat(r.OutputTokens/1000000, 1)))
	sb.WriteString(fmt.Sprintf("  Cost to Generate %s%s\n", CurrencySymbol, commaInt(int64(roundHalf(r.Cost)))))
	sb.WriteString(fmt.Sprintf("  Estimated Cycles %.1f\n", r.Cycles))
	sb.WriteString(fmt.Sprintf("  Generation Time (serial) %s\n", formatGenTime(r.GenerationSeconds)))
	sb.WriteString(fmt.Sprintf("  Human Review Time %s hours\n", commaFloat(r.ReviewHours, 1)))
	sb.WriteString("  Disclaimer: rough ballpark for regenerating code using a LLM.\n")
	sb.WriteString("  Does not account for context reuse, test generation, or heavy debugging.\n")
}

func sizeLine(b int64) string {
	unit := strings.ToLower(SizeUnit)
	var div float64
	label := "SI"
	switch unit {
	case "binary":
		div = 1024 * 1024
		label = "BINARY"
	case "mixed":
		div = 1000 * 1024
		label = "MIXED"
	case "xkcd-kb":
		div = 1e12
		label = "XKCD-KB"
	case "xkcd-kelly":
		div = 1012 * 1012
		label = "XKCD-KELLY"
	case "xkcd-imaginary":
		return fmt.Sprintf("Processed %d bytes, ¯\\_(ツ)_/¯ megabytes (XKCD-IMAGINARY)", b)
	case "xkcd-intel":
		div = 1023.937522 * 1023.937522
		label = "XKCD-INTEL"
	case "xkcd-drive":
		div = 732736
		label = "XKCD-DRIVE"
	case "xkcd-bakers":
		div = 1152 * 1152
		label = "XKCD-BAKERS"
	default:
		div = 1000 * 1000
	}
	return fmt.Sprintf("Processed %d bytes, %.3f megabytes (%s)", b, float64(b)/div, label)
}
