type jsonFile struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Hash               *struct{}
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
}

type jsonLang struct {
	Name               string
	Bytes              int64
	CodeBytes          int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	Count              int64
	WeightedComplexity float64
	Files              []jsonFile
	LineLength         []int
	ULOC               int
}

func toJSONFile(f *FileJob) jsonFile {
	jf := jsonFile{
		Language: f.Language, PossibleLanguages: f.PossibleLanguages, Filename: f.Filename,
		Extension: f.Extension, Location: f.Location, Symlocation: f.Symlocation, Bytes: f.Bytes,
		Lines: f.Lines, Code: f.Code, Comment: f.Comment, Blank: f.Blank, Complexity: f.Complexity,
		WeightedComplexity: f.WeightedComplexity, Binary: f.Binary, Minified: f.Minified, Generated: f.Generated,
		EndPoint: f.EndPoint, Uloc: f.Uloc,
	}
	if f.Hash != nil {
		jf.Hash = &struct{}{}
	}
	if jf.PossibleLanguages == nil {
		jf.PossibleLanguages = []string{}
	}
	return jf
}

func jsonLanguages(jobs []*FileJob) []jsonLang {
	langs := aggregate(jobs)
	sortSummaries(langs)
	out := []jsonLang{}
	for _, l := range langs {
		jl := jsonLang{Name: l.Name, Bytes: l.Bytes, Lines: l.Lines, Code: l.Code, Comment: l.Comment, Blank: l.Blank,
			Complexity: l.Complexity, Count: l.Count, WeightedComplexity: l.WeightedComplexity, Files: []jsonFile{}}
		if Files {
			for _, f := range l.Files {
				jl.Files = append(jl.Files, toJSONFile(f))
			}
		}
		if UlocMode {
			jl.ULOC = langUloc(l)
		}
		out = append(out, jl)
	}
	return out
}

func marshalNoEscape(v interface{}) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.Encode(v)
	return strings.TrimRight(buf.String(), "\n")
}

func toJSON(jobs []*FileJob) string {
	b, _ := json.Marshal(jsonLanguages(jobs))
	return string(b)
}

type json2Out struct {
	LanguageSummary         []jsonLang `json:"languageSummary"`
	EstimatedCost           float64    `json:"estimatedCost"`
	EstimatedScheduleMonths float64    `json:"estimatedScheduleMonths"`
	EstimatedPeople         float64    `json:"estimatedPeople"`
}

type json2OutLLM struct {
	LanguageSummary         []jsonLang `json:"languageSummary"`
	EstimatedCost           float64    `json:"estimatedCost"`
	EstimatedScheduleMonths float64    `json:"estimatedScheduleMonths"`
	EstimatedPeople         float64    `json:"estimatedPeople"`
	EstimatedLLMCost        float64    `json:"estimatedLLMCost"`
	EstimatedLLMInput       float64    `json:"estimatedLLMInputTokens"`
	EstimatedLLMOutput      float64    `json:"estimatedLLMOutputTokens"`
	EstimatedLLMGenSeconds  float64    `json:"estimatedLLMGenerationSeconds"`
	EstimatedLLMReviewHours float64    `json:"estimatedLLMReviewHours"`
	EstimatedLLMPreset      string     `json:"estimatedLLMPreset"`
	EstimatedLLMMult        float64    `json:"estimatedLLMAverageComplexityMultiplier"`
	EstimatedLLMCycles      float64    `json:"estimatedLLMCycles"`
}

func totals(jobs []*FileJob) (code, cx, lines, files, bytes int64) {
	for _, j := range jobs {
		code += j.Code
		cx += j.Complexity
		lines += j.Lines
		files++
		bytes += j.Bytes
	}
	return
}

func cocomoValues(code int64) (float64, float64, float64) {
	effort := estimateEffort(code, Eaf)
	cost := estimateCost(effort, AverageWage, Overhead)
	schedule := estimateSchedule(effort)
	people := effort / schedule
	return cost, schedule, people
}

func toJSON2(jobs []*FileJob) string {
	langs := jsonLanguages(jobs)
	code, cx, _, _, _ := totals(jobs)
	cost, schedule, people := cocomoValues(code)
	if Locomo || CostComparison {
		r := computeLocomo(code, cx)
		b, _ := json.Marshal(json2OutLLM{langs, cost, schedule, people, r.Cost, r.InputTokens, r.OutputTokens, r.GenerationSeconds, r.ReviewHours, r.Preset, r.ComplexityMult, r.Cycles})
		return string(b)
	}
	b, _ := json.Marshal(json2Out{langs, cost, schedule, people})
	return string(b)
}

func csvLine(fields []string) string {
	var buf bytes.Buffer
	w := csv.NewWriter(&buf)
	w.Write(fields)
	w.Flush()
	return buf.String()
}

func sortFilesCSV(files []*FileJob) {
	key := func(f *FileJob) int64 {
		switch SortBy {
		case "lines", "line":
			return f.Lines
		case "blank", "blanks":
			return f.Blank
		case "code":
			return f.Code
		case "comment", "comments":
			return f.Comment
		case "complexity":
			return f.Complexity
		case "bytes", "byte":
			return f.Bytes
		}
		return 0
	}
	switch SortBy {
	case "lines", "line", "blank", "blanks", "code", "comment", "comments", "complexity", "bytes", "byte":
		sort.SliceStable(files, func(i, j int) bool { return key(files[i]) > key(files[j]) })
	default:
		sort.SliceStable(files, func(i, j int) bool { return files[i].Filename < files[j].Filename })
	}
}

func toCSV(jobs []*FileJob) string {
	var sb strings.Builder
	if Files {
		sb.WriteString(csvLine([]string{"Language", "Provider", "Filename", "Lines", "Code", "Comments", "Blanks", "Complexity", "Bytes", "ULOC"}))
		files := append([]*FileJob{}, jobs...)
		sortFilesCSV(files)
		for _, f := range files {
			sb.WriteString(csvLine([]string{f.Language, f.Location, f.Filename, i64(f.Lines), i64(f.Code), i64(f.Comment), i64(f.Blank), i64(f.Complexity), i64(f.Bytes), fmt.Sprint(f.Uloc)}))
		}
		return sb.String()
	}
	sb.WriteString(csvLine([]string{"Language", "Lines", "Code", "Comments", "Blanks", "Complexity", "Bytes", "Files", "ULOC"}))
	langs := aggregate(jobs)
	sortSummaries(langs)
	for _, l := range langs {
		u := 0
		if UlocMode {
			u = langUloc(l)
		}
		sb.WriteString(csvLine([]string{l.Name, i64(l.Lines), i64(l.Code), i64(l.Comment), i64(l.Blank), i64(l.Complexity), i64(l.Bytes), i64(l.Count), fmt.Sprint(u)}))
	}
	return sb.String()
}

func i64(v int64) string { return fmt.Sprintf("%d", v) }

func toCSVStream(jobs []*FileJob) string {
	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")
	for _, f := range jobs {
		sb.WriteString(fmt.Sprintf("%s,\"%s\",\"%s\",%d,%d,%d,%d,%d,%d,%d\n", f.Language, f.Location, f.Filename, f.Lines, f.Code, f.Comment, f.Blank, f.Complexity, f.Bytes, f.Uloc))
	}
	return sb.String()
}

func toClocYAML(jobs []*FileJob) string {
	langs := aggregate(jobs)
	sort.SliceStable(langs, func(i, j int) bool { return langs[i].Name < langs[j].Name })
	var sb strings.Builder
	_, _, lines, files, _ := totals(jobs)
	elapsed := time.Since(startTime).Seconds()
	sb.WriteString("# https://github.com/boyter/scc/\nheader:\n  url: https://github.com/boyter/scc/\n")
	sb.WriteString(fmt.Sprintf("  version: %s\n", sccVersion))
	sb.WriteString(fmt.Sprintf("  elapsed_seconds: %.3f\n", elapsed))
	sb.WriteString(fmt.Sprintf("  n_files: %d\n", files))
	sb.WriteString(fmt.Sprintf("  n_lines: %d\n", lines))
	es := elapsed
	if es <= 0 {
		es = 0.001
	}
	sb.WriteString(fmt.Sprintf("  files_per_second: %d\n", int64(float64(files)/es)))
	sb.WriteString(fmt.Sprintf("  lines_per_second: %d\n", int64(float64(lines)/es)))
	var tc, tco, tb, tf int64
	for _, l := range langs {
		sb.WriteString(fmt.Sprintf("%s:\n  name: %s\n  code: %d\n  comment: %d\n  blank: %d\n  nFiles: %d\n", l.Name, l.Name, l.Code, l.Comment, l.Blank, l.Count))
		tc += l.Code
		tco += l.Comment
		tb += l.Blank
		tf += l.Count
	}
	sb.WriteString(fmt.Sprintf("SUM:\n  code: %d\n  comment: %d\n  blank: %d\n  nFiles: %d\n", tc, tco, tb, tf))
	return sb.String()
}

func htmlTable(jobs []*FileJob) string {
	langs := aggregate(jobs)
	sortSummaries(langs)
	var sb strings.Builder
	sb.WriteString("<table id=\"scc-table\">\n\t<thead><tr>\n\t\t<th>Language</th>\n\t\t<th>Files</th>\n\t\t<th>Lines</th>\n\t\t<th>Blank</th>\n\t\t<th>Comment</th>\n\t\t<th>Code</th>\n\t\t<th>Complexity</th>\n\t\t<th>Bytes</th>\n\t\t<th>Uloc</th>\n\t</tr></thead>\n\t<tbody>")
	var tf, tl, tb, tc, tco, tcx, tby int64
	for _, l := range langs {
		u := 0
		if UlocMode {
			u = langUloc(l)
		}
		sb.WriteString(fmt.Sprintf("<tr>\n\t\t<th>%s</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t</tr>", l.Name, l.Count, l.Lines, l.Blank, l.Comment, l.Code, l.Complexity, l.Bytes, u))
		if Files {
			files := append([]*FileJob{}, l.Files...)
			sortFiles(files)
			for _, f := range files {
				sb.WriteString(fmt.Sprintf("<tr>\n\t\t<td>%s</td>\n\t\t<td></td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t</tr>", f.Location, f.Lines, f.Blank, f.Comment, f.Code, f.Complexity, f.Bytes, f.Uloc))
			}
		}
		tf += l.Count
		tl += l.Lines
		tb += l.Blank
		tco += l.Comment
		tc += l.Code
		tcx += l.Complexity
		tby += l.Bytes
	}
	tu := 0
	if UlocMode {
		tu = totalUloc(jobs)
	}
	sb.WriteString(fmt.Sprintf("</tbody>\n\t<tfoot><tr>\n\t\t<th>Total</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t</tr>", tf, tl, tb, tco, tc, tcx, tby, tu))
	if !NoCocomo {
		var cb bytes.Buffer
		writeCocomo(&cb, tc)
		lines := strings.Split(strings.TrimRight(cb.String(), "\n"), "\n")
		sb.WriteString("\n\t<tr>\n\t\t<th colspan=\"9\">")
		for _, l := range lines {
			sb.WriteString(l + "<br>")
		}
		sb.WriteString("</th>\n\t</tr>")
	}
	sb.WriteString("</tfoot>\n\t</table>")
	return sb.String()
}

func toHTMLTable(jobs []*FileJob) string {
	return htmlTable(jobs)
}

func toHTML(jobs []*FileJob) string {
	return "<html lang=\"en\"><head><meta charset=\"utf-8\" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body>" + htmlTable(jobs) + "</body></html>\n"
}

var sqlCreate = `create table metadata (   -- github.com/boyter/scc v ` + sccVersion + `
             timestamp text,
             Project   text,
             elapsed_s real,
             estimated_cost real,
             estimated_schedule_months real,
             estimated_people real);
create table t        (
             Project       text   ,
             Language      text   ,
             File          text   ,
             File_dirname  text   ,
             File_basename text   ,
             nByte         integer,
             nBlank        integer,
             nComment      integer,
             nCode         integer,
             nComplexity   integer,
             nUloc         integer    
);`

var projectPaths []string

func sqlEscape(s string) string {
	return strings.ReplaceAll(s, "'", "''")
}

func sqlBody(jobs []*FileJob) string {
	var sb strings.Builder
	project := SQLProject
	if project == "" {
		project = strings.Join(projectPaths, ",")
	}
	sb.WriteString("\nbegin transaction;\n")
	for _, f := range jobs {
		base := filepath.Base(f.Location)
		dir := f.Location[:len(f.Location)-len(base)]
		sb.WriteString(fmt.Sprintf("insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n",
			sqlEscape(project), sqlEscape(f.Language), sqlEscape(f.Location), sqlEscape(dir), sqlEscape(base), f.Bytes, f.Blank, f.Comment, f.Code, f.Complexity, f.Uloc))
	}
	sb.WriteString("commit;\n")
	code, _, _, _, _ := totals(jobs)
	cost, schedule, people := cocomoValues(code)
	elapsed := float64(time.Since(startTime).Milliseconds()) / 1000
	sb.WriteString("begin transaction;\n")
	sb.WriteString(fmt.Sprintf("insert into metadata values('%s', '%s', %f, %f, %f, %f);\n", time.Now().Format("2006-01-02 15:04:05"), sqlEscape(project), elapsed, cost, schedule, people))
	sb.WriteString("commit;")
	return sb.String()
}

func toSQL(jobs []*FileJob) string {
	return sqlCreate + sqlBody(jobs)
}

func toSQLInsert(jobs []*FileJob) string {
	return sqlBody(jobs)
}

func toOpenMetrics(jobs []*FileJob) string {
	var sb strings.Builder
	sb.WriteString("# TYPE scc_files gauge\n# HELP scc_files Number of sourcecode files.\n# TYPE scc_lines gauge\n# HELP scc_lines Number of lines.\n# TYPE scc_code gauge\n# HELP scc_code Number of lines of actual code.\n# TYPE scc_comments gauge\n# HELP scc_comments Number of comments.\n# TYPE scc_blanks gauge\n# HELP scc_blanks Number of blank lines.\n# TYPE scc_complexity gauge\n# HELP scc_complexity Code complexity.\n# TYPE scc_bytes gauge\n# UNIT scc_bytes bytes\n# HELP scc_bytes Size in bytes.\n")
	langs := aggregate(jobs)
