			for _, f := range files {
				lab := fmt.Sprintf("{language=\"%s\",file=\"%s\"}", l.Name, f.Location)
				sb.WriteString(fmt.Sprintf("scc_lines%s %d\nscc_code%s %d\nscc_comments%s %d\nscc_blanks%s %d\nscc_complexity%s %d\nscc_bytes%s %d\n", lab, f.Lines, lab, f.Code, lab, f.Comment, lab, f.Blank, lab, f.Complexity, lab, f.Bytes))
			}
		}
