type jsonFile struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Hash               *struct{}
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
}

type jsonLang struct {
	Name               string
	Bytes              int64
	CodeBytes          int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	Count              int64
	WeightedComplexity float64
	Files              []jsonFile
	LineLength         []int
	ULOC               int
}

func toJSONFile(f *FileJob) jsonFile {
	jf := jsonFile{
		Language: f.Language, PossibleLanguages: f.PossibleLanguages, Filename: f.Filename,
		Extension: f.Extension, Location: f.Location, Symlocation: f.Symlocation, Bytes: f.Bytes,
		Lines: f.Lines, Code: f.Code, Comment: f.Comment, Blank: f.Blank, Complexity: f.Complexity,
		WeightedComplexity: f.WeightedComplexity, Binary: f.Binary, Minified: f.Minified, Generated: f.Generated,
		EndPoint: f.EndPoint, Uloc: f.Uloc,
	}
	if f.Hash != nil {
		jf.Hash = &struct{}{}
	}
	if jf.PossibleLanguages == nil {
		jf.PossibleLanguages = []string{}
	}
	return jf
}

func jsonLanguages(jobs []*FileJob) []jsonLang {
	langs := aggregate(jobs)
	sortSummaries(langs)
	out := []jsonLang{}
	for _, l := range langs {
		jl := jsonLang{Name: l.Name, Bytes: l.Bytes, Lines: l.Lines, Code: l.Code, Comment: l.Comment, Blank: l.Blank,
			Complexity: l.Complexity, Count: l.Count, WeightedComplexity: l.WeightedComplexity, Files: []jsonFile{}}
		if Files {
			for _, f := range l.Files {
				jl.Files = append(jl.Files, toJSONFile(f))
			}
		}
		if UlocMode {
			jl.ULOC = langUloc(l)
		}
		out = append(out, jl)
	}
	return out
}

func marshalNoEscape(v interface{}) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.Encode(v)
	return strings.TrimRight(buf.String(), "\n")
}

func toJSON(jobs []*FileJob) string {
	b, _ := json.Marshal(jsonLanguages(jobs))
	return string(b)
}

