}

var sqlCreate = `create table metadata (   -- github.com/boyter/scc v ` + sccVersion + `
             timestamp text,
             Project   text,
             elapsed_s real,
             estimated_cost real,
             estimated_schedule_months real,
             estimated_people real);
create table t        (
             Project       text   ,
             Language      text   ,
             File          text   ,
             File_dirname  text   ,
             File_basename text   ,
             nByte         integer,
             nBlank        integer,
             nComment      integer,
             nCode         integer,
             nComplexity   integer,
             nUloc         integer    
);`

var projectPaths []string

func sqlEscape(s string) string {
	return strings.ReplaceAll(s, "'", "''")
}

func sqlBody(jobs []*FileJob) string {
	var sb strings.Builder
	project := SQLProject
	if project == "" {
		project = strings.Join(projectPaths, ",")
	}
	sb.WriteString("\nbegin transaction;\n")
	for _, f := range jobs {
		base := filepath.Base(f.Location)
		dir := f.Location[:len(f.Location)-len(base)]
		sb.WriteString(fmt.Sprintf("insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n",
			sqlEscape(project), sqlEscape(f.Language), sqlEscape(f.Location), sqlEscape(dir), sqlEscape(base), f.Bytes, f.Blank, f.Comment, f.Code, f.Complexity, f.Uloc))
	}
	sb.WriteString("commit;\n")
	code, _, _, _, _ := totals(jobs)
	cost, schedule, people := cocomoValues(code)
	elapsed := float64(time.Since(startTime).Milliseconds()) / 1000
	sb.WriteString("begin transaction;\n")
	sb.WriteString(fmt.Sprintf("insert into metadata values('%s', '%s', %f, %f, %f, %f);\n", time.Now().Format("2006-01-02 15:04:05"), sqlEscape(project), elapsed, cost, schedule, people))
	sb.WriteString("commit;")
	return sb.String()
}

func toSQL(jobs []*FileJob) string {
	return sqlCreate + sqlBody(jobs)
}

func toSQLInsert(jobs []*FileJob) string {
	return sqlBody(jobs)
}

