	var sb strings.Builder
	sb.WriteString("# TYPE scc_files gauge\n# HELP scc_files Number of sourcecode files.\n# TYPE scc_lines gauge\n# HELP scc_lines Number of lines.\n# TYPE scc_code gauge\n# HELP scc_code Number of lines of actual code.\n# TYPE scc_comments gauge\n# HELP scc_comments Number of comments.\n# TYPE scc_blanks gauge\n# HELP scc_blanks Number of blank lines.\n# TYPE scc_complexity gauge\n# HELP scc_complexity Code complexity.\n# TYPE scc_bytes gauge\n# UNIT scc_bytes bytes\n# HELP scc_bytes Size in bytes.\n")
	langs := aggregate(jobs)
	sortSummaries(langs)
	if Files {
		for _, l := range langs {
			files := append([]*FileJob{}, l.Files...)
			for _, f := range files {
				lab := fmt.Sprintf("{language=\"%s\",file=\"%s\"}", l.Name, f.Location)
				sb.WriteString(fmt.Sprintf("scc_lines%s %d\nscc_code%s %d\nscc_comments%s %d\nscc_blanks%s %d\nscc_complexity%s %d\nscc_bytes%s %d\n", lab, f.Lines, lab, f.Code, lab, f.Comment, lab, f.Blank, lab, f.Complexity, lab, f.Bytes))
			}
		}
		return sb.String()
	}
	for _, l := range langs {
		lab := fmt.Sprintf("{language=\"%s\"}", l.Name)
		sb.WriteString(fmt.Sprintf("scc_files%s %d\nscc_lines%s %d\nscc_code%s %d\nscc_comments%s %d\nscc_blanks%s %d\nscc_complexity%s %d\nscc_bytes%s %d\n", lab, l.Count, lab, l.Lines, lab, l.Code, lab, l.Comment, lab, l.Blank, lab, l.Complexity, lab, l.Bytes))
	}
	return sb.String()
}

