//go:embed mcp_tools.json
var mcpToolsJSON string

var mcpOutMu sync.Mutex
var mcpRunMu sync.Mutex

func mcpWrite(s string) {
	mcpOutMu.Lock()
	defer mcpOutMu.Unlock()
	os.Stdout.WriteString(s + "\n")
}

func mcpIDString(id json.RawMessage) string {
	if len(id) == 0 {
		return "null"
	}
	return string(id)
}

func mcpError(id json.RawMessage, code int, msg string) {
	m, _ := json.Marshal(msg)
	mcpWrite(fmt.Sprintf(`{"jsonrpc":"2.0","id":%s,"error":{"code":%d,"message":%s}}`, mcpIDString(id), code, string(m)))
}

func mcpResult(id json.RawMessage, result string) {
	mcpWrite(fmt.Sprintf(`{"jsonrpc":"2.0","id":%s,"result":%s}`, mcpIDString(id), result))
}

func mcpServe() {
	reader := bufio.NewReader(os.Stdin)
	var wg sync.WaitGroup
	for {
		line, err := reader.ReadString('\n')
		if strings.TrimSpace(line) != "" {
			handleMCPLine(strings.TrimSpace(line), &wg)
		}
		if err != nil {
			break
		}
	}
	wg.Wait()
}

func handleMCPLine(line string, wg *sync.WaitGroup) {
	var raw json.RawMessage
	if err := json.Unmarshal([]byte(line), &raw); err != nil {
		mcpError(nil, -32700, "Parse error")
		return
	}
	var msg struct {
		JSONRPC string          `json:"jsonrpc"`
		ID      json.RawMessage `json:"id"`
		Method  string          `json:"method"`
		Params  json.RawMessage `json:"params"`
	}
	if err := json.Unmarshal([]byte(line), &msg); err != nil {
		mcpError(nil, -32700, "Failed to parse message")
		return
	}
	if msg.JSONRPC != "2.0" {
		mcpError(msg.ID, -32600, "Invalid JSON-RPC version")
		return
	}
	isNotification := len(msg.ID) == 0 || string(msg.ID) == "null"
	if isNotification {
		return
	}
	switch msg.Method {
	case "initialize":
		var p struct {
			ProtocolVersion string `json:"protocolVersion"`
		}
		json.Unmarshal(msg.Params, &p)
		v := p.ProtocolVersion
		switch v {
		case "":
			v = "2025-03-26"
		case "2024-11-05", "2025-03-26", "2025-06-18", "2025-11-25":
		default:
			v = "2025-11-25"
		}
		mcpResult(msg.ID, fmt.Sprintf(`{"protocolVersion":%q,"capabilities":{"tools":{}},"serverInfo":{"name":"scc","version":%q}}`, v, sccVersion))
	case "ping":
		mcpResult(msg.ID, "{}")
	case "tools/list":
		mcpResult(msg.ID, mcpToolsJSON)
	case "tools/call":
		var p struct {
			Name      string                 `json:"name"`
			Arguments map[string]interface{} `json:"arguments"`
		}
		json.Unmarshal(msg.Params, &p)
		if p.Name != "analyze" {
			mcpError(msg.ID, -32602, fmt.Sprintf("tool '%s' not found: tool not found", p.Name))
			return
		}
		id := msg.ID
		wg.Add(1)
		go func() {
			defer wg.Done()
			mcpRunMu.Lock()
			text, isErr := mcpAnalyze(p.Arguments)
			mcpRunMu.Unlock()
			t, _ := json.Marshal(text)
			if isErr {
				mcpResult(id, fmt.Sprintf(`{"content":[{"type":"text","text":%s}],"isError":true}`, string(t)))
			} else {
				mcpResult(id, fmt.Sprintf(`{"content":[{"type":"text","text":%s}]}`, string(t)))
			}
		}()
	case "resources/list", "resources/read", "resources/templates/list", "resources/subscribe", "resources/unsubscribe":
		mcpError(msg.ID, -32601, "resources not supported")
	case "prompts/list", "prompts/get":
		mcpError(msg.ID, -32601, "prompts not supported")
	case "logging/setLevel":
		mcpError(msg.ID, -32601, "logging not supported")
	default:
		mcpError(msg.ID, -32601, fmt.Sprintf("Method %s not found", msg.Method))
	}
}

