	Cocomo     mcpCocomo  `json:"cocomo"`
	Locomo     *mcpLocomo `json:"locomo,omitempty"`
	TotalFiles int64      `json:"totalFiles"`
	TotalLines int64      `json:"totalLines"`
	TotalCode  int64      `json:"totalCode"`
}

func argString(a map[string]interface{}, k string) string {
	if v, ok := a[k]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

func argBool(a map[string]interface{}, k string) bool {
	if v, ok := a[k]; ok {
		if b, ok := v.(bool); ok {
			return b
		}
	}
	return false
}

func argNumber(a map[string]interface{}, k string, def float64) float64 {
	if v, ok := a[k]; ok {
		if f, ok := v.(float64); ok {
			return f
		}
	}
	return def
}

func splitCSV(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ",") {
		p = strings.TrimSpace(p)
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

func mcpAnalyze(args map[string]interface{}) (string, bool) {
	if args == nil {
		args = map[string]interface{}{}
	}
	path := argString(args, "path")
	if path == "" {
		path = "."
	}
	abs, err := filepath.Abs(path)
	if err == nil {
		path = abs
	}
	if _, err := os.Stat(path); err != nil {
		return fmt.Sprintf("path cannot be accessed: %s: %s", path, err.Error()), true
	}
	// save globals
	saveAllow, saveExclude, saveDup := AllowListExtensions, ExcludeExt, Duplicates
	saveMG, saveIMG, saveMin, saveGen := MinifiedGenerated, IgnoreMinifiedGenerated, Minified, Generated
	saveSort, savePreset := SortBy, LocomoPreset
	defer func() {
		AllowListExtensions, ExcludeExt, Duplicates = saveAllow, saveExclude, saveDup
		MinifiedGenerated, IgnoreMinifiedGenerated, Minified, Generated = saveMG, saveIMG, saveMin, saveGen
		SortBy, LocomoPreset = saveSort, savePreset
	}()
	AllowListExtensions = splitCSV(argString(args, "include_ext"))
	ExcludeExt = splitCSV(argString(args, "exclude_ext"))
	Duplicates = argBool(args, "no_duplicates")
	if argBool(args, "no_min_gen") {
		MinifiedGenerated = true
		IgnoreMinifiedGenerated = true
		Minified = true
		Generated = true
	}
	sortBy := argString(args, "sort")
	if sortBy == "" {
		sortBy = "files"
	}
	SortBy = sortBy
	if p := argString(args, "locomo_preset"); p != "" {
		LocomoPreset = p
	}
	files := walkPaths([]string{path})
	jobs := processFiles(files)
	langs := aggregate(jobs)
	sortSummaries(langs)
	byFile := argBool(args, "by_file")
	limit := int(argNumber(args, "limit", 10))
	body := mcpResultBody{Path: path, Languages: []mcpLang{}}
	for _, l := range langs {
		ml := mcpLang{Name: l.Name, Files: l.Count, Lines: l.Lines, Code: l.Code, Comment: l.Comment, Blank: l.Blank, Complexity: l.Complexity, Bytes: l.Bytes}
		if byFile {
			fs := append([]*FileJob{}, l.Files...)
			sortFiles(fs)
			if limit >= 0 && len(fs) > limit {
				fs = fs[:limit]
			}
			for _, f := range fs {
				ml.FileList = append(ml.FileList, mcpFile{Location: f.Location, Filename: f.Filename, Language: f.Language, Lines: f.Lines, Code: f.Code, Comment: f.Comment, Blank: f.Blank, Complexity: f.Complexity, Bytes: f.Bytes})
			}
		}
		body.Languages = append(body.Languages, ml)
		body.Totals.Files += l.Count
		body.Totals.Lines += l.Lines
		body.Totals.Code += l.Code
		body.Totals.Comment += l.Comment
		body.Totals.Blank += l.Blank
		body.Totals.Complexity += l.Complexity
		body.Totals.Bytes += l.Bytes
	}
	cost, schedule, people := cocomoValues(body.Totals.Code)
	body.Cocomo = mcpCocomo{cost, schedule, people}
	if argBool(args, "locomo") {
		r := computeLocomo(body.Totals.Code, body.Totals.Complexity)
		body.Locomo = &mcpLocomo{r.Cost, r.InputTokens, r.OutputTokens, r.GenerationSeconds, r.ReviewHours, r.Preset, r.ComplexityMult, r.Cycles}
	}
	body.TotalFiles = body.Totals.Files
	body.TotalLines = body.Totals.Lines
	body.TotalCode = body.Totals.Code
	b, _ := json.MarshalIndent(body, "", "  ")
	return string(b), false
}

