	ar, br := []rune(a), []rune(b)
	digits := false
	for i := 0; i < len(ar) && i < len(br); i++ {
		if ar[i] == br[i] {
			digits = unicode.IsDigit(ar[i])
			continue
		}
		al := unicode.IsLetter(ar[i])
		bl := unicode.IsLetter(br[i])
		if al && bl {
			return ar[i] < br[i]
		}
		if al || bl {
			if digits {
				return al
			}
			return bl
		}
		var ai, bi int
		var an, bn int64
		if ar[i] == '0' || br[i] == '0' {
			for j := i - 1; j >= 0 && unicode.IsDigit(ar[j]); j-- {
				if ar[j] != '0' {
					an = 1
					bn = 1
					break
				}
			}
		}
		for ai = i; ai < len(ar) && unicode.IsDigit(ar[ai]); ai++ {
			an = an*10 + int64(ar[ai]-'0')
		}
		for bi = i; bi < len(br) && unicode.IsDigit(br[bi]); bi++ {
			bn = bn*10 + int64(br[bi]-'0')
		}
		if an != bn {
			return an < bn
		}
		if ai != bi {
			return ai < bi
		}
		return ar[i] < br[i]
	}
	return len(ar) < len(br)
}

func yamlFloat(f float64) string {
	s := strconv.FormatFloat(f, 'g', -1, 64)
	switch s {
	case "+Inf":
		return ".inf"
	case "-Inf":
		return "-.inf"
	case "NaN":
		return ".nan"
	}
	return s
}

func yamlScalar(s string) string {
	needs := false
	if s == "" {
		needs = true
	} else {
		switch strings.ToLower(s) {
		case "y", "yes", "n", "no", "true", "false", "on", "off", "null", "~":
			needs = true
		}
		if strings.ContainsAny(s[:1], "!&*-?:,[]{}#|>@`\\"'%") || strings.Contains(s, ": ") || strings.Contains(s, " #") || strings.HasSuffix(s, ":") || strings.HasSuffix(s, " ") {
			needs = true
		}
	}
	if needs {
		return "\\"" + strings.ReplaceAll(strings.ReplaceAll(s, "\\\\", "\\\\\\\\"), "\\"", "\\\\\\"") + "\\""
	}
	return s
}

func toClocYAML(jobs []*FileJob) string {
	langs := aggregate(jobs)
	sort.SliceStable(langs, func(i, j int) bool { return yamlKeyLess(langs[i].Name, langs[j].Name) })
	var sb strings.Builder
	_, _, lines, files, _ := totals(jobs)
	elapsed := float64(time.Since(startTime).Milliseconds()) / 1000
	sb.WriteString("# https://github.com/boyter/scc/\\nheader:\\n  url: https://github.com/boyter/scc/\\n")
	sb.WriteString(fmt.Sprintf("  version: %s\\n", sccVersion))
	sb.WriteString(fmt.Sprintf("  elapsed_seconds: %s\\n", yamlFloat(elapsed)))
	sb.WriteString(fmt.Sprintf("  n_files: %d\\n", files))
	sb.WriteString(fmt.Sprintf("  n_lines: %d\\n", lines))
	sb.WriteString(fmt.Sprintf("  files_per_second: %s\\n", yamlFloat(float64(files)/elapsed)))
	sb.WriteString(fmt.Sprintf("  lines_per_second: %s\\n", yamlFloat(float64(lines)/elapsed)))
	var tc, tco, tb, tf int64
	if len(langs) == 0 {
		sb.WriteString("{}\\n")
	}
	for _, l := range langs {
		sb.WriteString(fmt.Sprintf("%s:\\n  name: %s\\n  code: %d\\n  comment: %d\\n  blank: %d\\n  nFiles: %d\\n", yamlScalar(l.Name), yamlScalar(l.Name), l.Code, l.Comment, l.Blank, l.Count))
		tc += l.Code
		tco += l.Comment
		tb += l.Blank
		tf += l.Count
	}
	sb.WriteString(fmt.Sprintf("SUM:\\n  code: %d\\n  comment: %d\\n  blank: %d\\n  nFiles: %d\\n", tc, tco, tb, tf))
	return sb.String()
}

