package main

import (
	"embed"
	"fmt"
	"os"
	"strings"
)

//go:embed completions/*.txt
var completionFS embed.FS

func readCompletion(name string) string {
	b, err := completionFS.ReadFile("completions/" + name + ".txt")
	if err != nil {
		return ""
	}
	return string(b)
}

// boolFlagNames returns long/short names of boolean flags (used to skip flag values)
func isValueFlag(fs *flagSet, arg string) bool {
	if strings.HasPrefix(arg, "--") {
		name := arg[2:]
		if strings.Contains(name, "=") {
			return false
		}
		if d, ok := fs.long[name]; ok {
			return d.kind != kBool
		}
		return false
	}
	if strings.HasPrefix(arg, "-") && len(arg) == 2 {
		if d, ok := fs.short[arg[1:]]; ok {
			return d.kind != kBool
		}
	}
	return false
}

// handleCompletion checks if the command line refers to the completion sub command.
func handleCompletion(fs *flagSet, args []string) bool {
	idx := -1
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			return false
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			if isValueFlag(fs, a) {
				i++
			}
			continue
		}
		if a == "completion" {
			idx = i
		}
		break
	}
	if idx == -1 {
		return false
	}
	rest := args[idx+1:]
	shell := ""
	help := false
	noDesc := false
	for _, a := range rest {
		switch {
		case a == "-h" || a == "--help":
			help = true
		case a == "--no-descriptions":
			noDesc = true
		case strings.HasPrefix(a, "-"):
		default:
			if shell == "" {
				shell = a
			}
		}
	}
	switch shell {
	case "bash", "zsh", "fish", "powershell":
		if help {
			fmt.Print(readCompletion(shell + "_help"))
		} else if noDesc {
			fmt.Print(readCompletion(shell + "_nodesc"))
		} else {
			fmt.Print(readCompletion(shell))
		}
	default:
		fmt.Print(readCompletion("help"))
	}
	os.Exit(0)
	return true
}
EOF
